from functools import reduce
from typing import Callable

def pipe(*fns: Callable):
    return lambda x: reduce(lambda v, f: f(v), fns, x)

procesar = pipe(
    lambda s: s.strip(),
    lambda s: s.upper(),
    lambda s: f"[{s}]",
)
print(processar("  apexType  "))

package main

import (
  "fmt"
  "sync"
)

func main() {
  var wg sync.WaitGroup
  for i := 1; i <= 3; i++ {
    wg.Add(1)
    go func(n int) {
      defer wg.Done()
      fmt.Printf("goroutine %d done\n", n)
    }(i)
  }
  wg.Wait()
}

